INSERT INTO cursos (id, titulo, area, nivel, duracion_semanas, modalidad, fase, docente_id, instructor, edad_minima, descripcion, objetivo, temario, modulos, guia, proyecto) VALUES (1, 'Lógica de programación', 'Software', 'Básico', 2, 'Presencial', 'Lanzamiento', (SELECT id FROM usuarios WHERE nombre = 'Por asignar' AND rol = 'docente'), 'Por asignar', 14, 'El punto de partida de la ruta. Antes de escribir código aprendes a pensar como programador: descomponer un problema en pasos, escribir algoritmos y usar variables, decisiones y ciclos. No necesitas saber nada de programación.', 'Resolver problemas sencillos paso a paso con algoritmos.', ARRAY['Pensar en pasos: Problema, entradas y salidas, algoritmos y pseudocódigo, diagramas de flujo', 'Variables, decisiones y ciclos: Variables y operadores, condicionales, ciclos']::text[], '[{"titulo":"Pensar en pasos","temas":["Problema, entradas y salidas","Algoritmos y pseudocódigo","Diagramas de flujo"],"temasTexto":"Problema, entradas y salidas, algoritmos y pseudocódigo, diagramas de flujo","actividades":["Convertir una rutina diaria en un algoritmo claro, paso a paso."],"evidencia":"Algoritmo escrito paso a paso."},{"titulo":"Variables, decisiones y ciclos","temas":["Variables y operadores","Condicionales","Ciclos"],"temasTexto":"Variables y operadores, condicionales, ciclos","actividades":["Escribir en PSeInt el juego de adivinar el número."],"evidencia":"Archivo de PSeInt con el juego funcionando."}]'::jsonb, '{"modalidad":"Clase presencial en Barranquilla: plantea un problema cotidiano, resuélvelo en el tablero con el grupo y deja que cada estudiante lo pase a PSeInt.","nota":"","reto":"Cambia el juego para que avise si el número está cerca o lejos.","preguntas":["¿Qué datos necesita tu algoritmo?","¿Qué decisión toma?","¿Qué se repite?"]}'::jsonb, 'Un juego de adivinar el número, escrito en pseudocódigo.');
INSERT INTO cursos (id, titulo, area, nivel, duracion_semanas, modalidad, fase, docente_id, instructor, edad_minima, descripcion, objetivo, temario, modulos, guia, proyecto) VALUES (2, 'Git y GitHub', 'Software', 'Básico', 2, 'Presencial', 'Lanzamiento', (SELECT id FROM usuarios WHERE nombre = 'Por asignar' AND rol = 'docente'), 'Por asignar', 14, 'Aprendes a guardar el historial de tu código y a trabajar como lo hacen los equipos de verdad. Desde aquí, todo lo que hagas en la ruta queda guardado y publicado en GitHub.', 'Guardar el historial de tus proyectos con Git y publicarlos en GitHub.', ARRAY['Tu primer repositorio: Qué es el control de versiones, git init, add y commit, ver el historial', 'Trabajar con GitHub: Subir con push, ramas, pull requests']::text[], '[{"titulo":"Tu primer repositorio","temas":["Qué es el control de versiones","git init, add y commit","Ver el historial"],"temasTexto":"Qué es el control de versiones, git init, add y commit, ver el historial","actividades":["Crear un repositorio y guardar tus ejercicios de lógica con varios commits."],"evidencia":"Repositorio con al menos tres commits."},{"titulo":"Trabajar con GitHub","temas":["Subir con push","Ramas","Pull requests"],"temasTexto":"Subir con push, ramas, pull requests","actividades":["Subir tu repositorio a GitHub y proponer un cambio desde una rama."],"evidencia":"Enlace a tu repositorio en GitHub."}]'::jsonb, '{"modalidad":"Clase presencial en Barranquilla: muestra cada comando en pantalla, deja que lo repitan en su computador y revisen juntos el historial.","nota":"","reto":"Crea una rama nueva, cambia un archivo y únela a la rama principal.","preguntas":["¿Qué guardó tu commit?","¿Cómo vuelves a una versión anterior?","¿Para qué sirve una rama?"]}'::jsonb, 'Tu primer repositorio en GitHub con los ejercicios de la ruta.');
INSERT INTO cursos (id, titulo, area, nivel, duracion_semanas, modalidad, fase, docente_id, instructor, edad_minima, descripcion, objetivo, temario, modulos, guia, proyecto) VALUES (3, 'HTML y CSS: tu primera página web', 'Software', 'Básico', 2, 'Presencial', 'Lanzamiento', (SELECT id FROM usuarios WHERE nombre = 'Por asignar' AND rol = 'docente'), 'Por asignar', 14, 'Aprendes cómo está hecha una página web, escribes su estructura con HTML y le das estilo con CSS hasta que se vea bien en el celular y en el computador. Al final la publicas en internet con GitHub Pages.', 'Construir y publicar una página web sencilla, ordenada y que se vea bien en cualquier pantalla.', ARRAY['Estructura con HTML: Cómo funciona una página web, etiquetas y estructura, enlaces e imágenes', 'Diseño con CSS y publicación: Colores, fuentes y modelo de caja, diseño responsive, publicar con GitHub Pages']::text[], '[{"titulo":"Estructura con HTML","temas":["Cómo funciona una página web","Etiquetas y estructura","Enlaces e imágenes"],"temasTexto":"Cómo funciona una página web, etiquetas y estructura, enlaces e imágenes","actividades":["Escribir la estructura de una página sobre ti con títulos, párrafos, una imagen y enlaces."],"evidencia":"Archivo index.html con la estructura de tu página."},{"titulo":"Diseño con CSS y publicación","temas":["Colores, fuentes y modelo de caja","Diseño responsive","Publicar con GitHub Pages"],"temasTexto":"Colores, fuentes y modelo de caja, diseño responsive, publicar con GitHub Pages","actividades":["Darle estilo a tu página, hacer que se vea bien en el celular y publicarla."],"evidencia":"Enlace público de tu página."}]'::jsonb, '{"modalidad":"Clase presencial en Barranquilla: explica con un ejemplo en pantalla, deja que cada estudiante lo repita en su página y cierra mostrando el avance de dos o tres personas.","nota":"","reto":"Agrega una sección nueva a tu página y comprueba que se siga viendo bien en un celular.","preguntas":["¿Qué ve primero la persona que entra a tu página?","¿Cómo se ve en una pantalla pequeña?","¿Cómo lo comprobarías?"]}'::jsonb, 'Tu página personal publicada en internet con GitHub Pages.');
INSERT INTO cursos (id, titulo, area, nivel, duracion_semanas, modalidad, fase, docente_id, instructor, edad_minima, descripcion, objetivo, temario, modulos, guia, proyecto) VALUES (4, 'JavaScript para principiantes', 'Software', 'Básico', 2, 'Presencial', 'Lanzamiento', (SELECT id FROM usuarios WHERE nombre = 'Por asignar' AND rol = 'docente'), 'Por asignar', 14, 'Le das vida a tu página: botones que responden, contenido que cambia y formularios que revisan lo que escribe la persona. Usas lo que aprendiste en lógica de programación, ahora con código de verdad.', 'Programar la interacción de una página web con JavaScript.', ARRAY['Bases de JavaScript: Variables y tipos de datos, condicionales y ciclos, funciones', 'JavaScript en tu página: El DOM, eventos y clics, validar formularios']::text[], '[{"titulo":"Bases de JavaScript","temas":["Variables y tipos de datos","Condicionales y ciclos","Funciones"],"temasTexto":"Variables y tipos de datos, condicionales y ciclos, funciones","actividades":["Crear una calculadora de descuentos para una tienda del barrio."],"evidencia":"Calculadora funcionando en el navegador."},{"titulo":"JavaScript en tu página","temas":["El DOM","Eventos y clics","Validar formularios"],"temasTexto":"El DOM, eventos y clics, validar formularios","actividades":["Agregar a tu página un menú, un modo oscuro y un formulario que revisa los datos."],"evidencia":"Tu página publicada con JavaScript."}]'::jsonb, '{"modalidad":"Clase presencial en Barranquilla: programa en vivo pensando en voz alta, deja que cada estudiante lo repita y revisen juntos los errores de la consola.","nota":"","reto":"Agrega un botón nuevo que cambie algo de la página y explica qué pasa paso a paso.","preguntas":["¿Qué pasa cuando la persona hace clic?","¿Qué pasa si escribe algo que no esperabas?","¿Cómo lo compruebas en la consola?"]}'::jsonb, 'Tu página con un menú, un modo oscuro y un formulario que valida los datos.');
INSERT INTO cursos (id, titulo, area, nivel, duracion_semanas, modalidad, fase, docente_id, instructor, edad_minima, descripcion, objetivo, temario, modulos, guia, proyecto) VALUES (5, 'Bases de datos con SQL', 'Software', 'Básico', 2, 'Presencial', 'Lanzamiento', (SELECT id FROM usuarios WHERE nombre = 'Por asignar' AND rol = 'docente'), 'Por asignar', 14, 'La última pieza de la ruta: guardar información. Aprendes qué es una base de datos, a crear tablas y a consultarlas con SQL usando PostgreSQL, como lo hacen las aplicaciones de verdad.', 'Crear una base de datos sencilla y consultarla con SQL.', ARRAY['Tablas y datos: Qué es una base de datos, tablas, filas y columnas, CREATE TABLE e INSERT', 'Consultas con SQL: SELECT y WHERE, UPDATE y DELETE, relacionar tablas con JOIN']::text[], '[{"titulo":"Tablas y datos","temas":["Qué es una base de datos","Tablas, filas y columnas","CREATE TABLE e INSERT"],"temasTexto":"Qué es una base de datos, tablas, filas y columnas, CREATE TABLE e INSERT","actividades":["Crear en PostgreSQL la tabla de contactos de tu página y llenarla."],"evidencia":"Script SQL que crea y llena la tabla."},{"titulo":"Consultas con SQL","temas":["SELECT y WHERE","UPDATE y DELETE","Relacionar tablas con JOIN"],"temasTexto":"SELECT y WHERE, UPDATE y DELETE, relacionar tablas con JOIN","actividades":["Responder preguntas sobre tus datos con consultas SQL y presentar tu proyecto de la ruta."],"evidencia":"Archivo con las consultas y sus resultados."}]'::jsonb, '{"modalidad":"Clase presencial en Barranquilla: diseña la tabla en el tablero con el grupo, escribe las consultas en vivo y cierra con la presentación de los proyectos de la ruta.","nota":"","reto":"Agrega una tabla nueva y únela a la de contactos con JOIN.","preguntas":["¿Qué información necesitas guardar?","¿Cómo encuentras un dato?","¿Qué pasa si borras un registro?"]}'::jsonb, 'La base de datos de los contactos de tu página, con sus consultas en SQL.');
